def min_Jumps(point, length):
    x, y = point
    if x == 0 and y == 0:
        return 0
    if x < 0 or y < 0:
        return float('inf')
    if x == y:
        return 1
    if x > y:
        return math.sqrt((x - y) ** 2)
    return math.sqrt((x - y) ** 2) + min_Jumps((x - y, y), length)

