    s = str(n)

    # Initialize a dictionary to keep track of the frequency of each digit
    freq = {}

    # Iterate over each digit in the string
    for digit in s:
        # Convert the digit back to an integer
        digit = int(digit)

        # Increment the count of the digit in the dictionary
        if digit in freq:
            freq[digit] += 1
        else:
            freq[digit] = 1

    # Iterate over the dictionary
    for digit, count in freq.items():
        # Check if the frequency is greater than the digit itself
        if count > digit:
            return False

