def get_Char(s):
    sum_ascii = 0
    for c in s:
        sum_ascii += ord(c)
    return chr((sum_ascii % 26) + 97)

def decimal_to_binary(decimal_number):
    binary_string = ""
    while decimal_number > 0:
        binary_string = str(decimal_number % 2) + binary_string
        decimal_number //= 2
    return binary_string
